def backfill_legacy_orders(apps, schema_editor):
    """Orders placed before GST existed: total was the taxable value and carried no GST."""
    Order = apps.get_model("shop", "Order")
    for order in Order.objects.all():
        gross = sum(item.unit_price * item.quantity for item in order.items.all())
        order.taxable_value = order.total
        order.subtotal = max(gross, order.total)
        order.discount = order.subtotal - order.total
        order.gst_rate = 0
        order.cgst = 0
        order.sgst = 0
        order.save()



